{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS prd_db.justherbs.dwh_UTM_MAPPING ( UTM_SOURCE VARCHAR(16777216), UTM_MEDIUM VARCHAR(16777216), CHANNEL VARCHAR(16777216) ); CREATE TABLE IF NOT EXISTS prd_db.justherbs.dwh_SKU_MASTER ( skucode VARCHAR(16777216), name VARCHAR(16777216), category VARCHAR(16777216), sub_category VARCHAR(16777216) ); CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_customers AS select *, \'Shopify_justherbs\' AS Shop_Name from datalake_db.justherbs.trn_Shopify_jh_CUSTOMERS; create or replace table prd_db.justherbs.dwh_Shopify_jh_UTM_Parameters as with deduped_utm_mapping as ( select * from datalake_db.justherbs.mst_utm_mapping where utm_source is not null qualify row_number() over (partition by lower(utm_source) order by 1) = 1 ) select ShopifyQL.*, upper(coalesce(UTM_MAPPING.CHANNEL, UTM_MAPPING_REF.CHANNEL, ShopifyQL.ShopifyQL_Unmapped_Last_Source)) as ShopifyQL_MAPPED_CHANNEL, upper(coalesce(UTM_MAPPING.UTM_SOURCE, UTM_MAPPING_REF.UTM_SOURCE, ShopifyQL.ShopifyQL_Unmapped_Last_Source)) as ShopifyQL_MAPPED_SOURCE from ( select A.id, A.name, A.createdat, coalesce( CUSTOMERJOURNEYSUMMARY:\"momentsCount\":\"count\", customerjourneysummary:\"momentsCount\" ) Moments_Count, replace(A.customerjourneysummary:\"daysToConversion\", \'\"\', \'\') DaysToConvert, replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"source\", \'\"\', \'\') LastVisit_UTM_Source, replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"source\", \'\"\', \'\') LastVisit_NON_UTM_Source, replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"campaign\", \'\"\', \'\') LastVisit_UTM_Campaign, replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"source\", \'\"\', \'\') FirstVisit_UTM_Source, replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"medium\", \'\"\', \'\') FirstVisit_UTM_Medium, replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"campaign\", \'\"\', \'\') FirstVisit_UTM_Campaign, replace(B.Value:\"id\", \'gid://shopify/CustomerVisit/\', \'\') Moment_ID, replace(B.value:\"utmParameters\":\"source\", \'\"\', \'\') Last_Moment_UTM_Source, replace(B.value:\"utmParameters\":\"medium\", \'\"\', \'\') Last_Moment_UTM_Medium, case when Moments_Count > 1 then LastVisit_UTM_Source else FirstVisit_UTM_Source end CJSummary_utm_source, referrerdisplaytext Referrer_Name, customerjourneysummary, customerjourney, coalesce(Last_Moment_UTM_Source, LastVisit_NON_UTM_Source) ShopifyQL_Unmapped_Last_Source from datalake_db.justherbs.TRN_SHOPIFY_JH_UTM_PARAMETERS A, lateral flatten (INPUT => customerjourney:\"moments\", OUTER => TRUE) B qualify rank() over (partition by name order by Moment_ID desc) = 1 ) ShopifyQL left join deduped_utm_mapping UTM_MAPPING on lower(ShopifyQL.ShopifyQL_Unmapped_Last_Source) = lower(UTM_MAPPING.utm_source) left join deduped_utm_mapping UTM_MAPPING_REF on lower(ShopifyQL.referrer_name) = lower(UTM_MAPPING_REF.utm_source) left join deduped_utm_mapping UTM_MAPPING_FIRST_CLICK on lower(ShopifyQL.FirstVisit_UTM_Source) = lower(UTM_MAPPING_FIRST_CLICK.utm_source); create or replace table prd_db.justherbs.dwh_GOKWIK_SOURCE as with GO_KWIK as ( select S.id, S.tags, MAX(case when LOWER(A.value:\"name\") = \'utm_source\' then UPPER(A.value:\"value\") end) AS GOKWIK_UTM_SOURCE, MAX(case when LOWER(A.value:\"name\") = \'utm_medium\' then UPPER(A.value:\"value\") end) AS GOKWIK_UTM_MEDIUM, MAX(case when LOWER(A.value:\"name\") = \'utm_campaign\' then UPPER(A.value:\"value\") end) AS GOKWIK_UTM_CAMPAIGN, MAX(case when LOWER(A.value:\"name\") = \'utm_content\' then UPPER(A.value:\"value\") end) AS GOKWIK_UTM_CONTENT from datalake_db.justherbs.trn_Shopify_jh_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") in (\'utm_source\', \'utm_medium\', \'utm_campaign\', \'utm_content\') group by S.id, S.tags ) Select GO_KWIK.*, coalesce(Upper(UTM_MAPPING.CHANNEL), upper(GOKWIK_UTM_MEDIUM)) as GOKWIK_MAPPED_CHANNEL, coalesce(Upper(UTM_MAPPING.CHANNEL), upper(GOKWIK_UTM_SOURCE)) as GOKWIK_MAPPED_SOURCE from GO_KWIK left join ( select * from datalake_db.justherbs.mst_utm_mapping where lower(concat(ifnull(utm_source, \'\'), ifnull(utm_medium, \'\'))) is not null qualify row_number() over ( partition by lower(concat(ifnull(utm_source, \'\'), ifnull(utm_medium, \'\'))) order by 1 ) = 1 ) UTM_MAPPING on lower( concat(ifnull(trim(GO_KWIK.GOKWIK_UTM_SOURCE), \'\'), ifnull(trim(GOKWIK_UTM_MEDIUM), \'\')) ) = lower( concat(ifnull(UTM_MAPPING.utm_source, \'\'), ifnull(UTM_MAPPING.utm_medium, \'\')) ); create or replace table prd_db.justherbs.dwh_Shopify_All_orders as select AO.*, UPPER(ShopifyQL.shopifyql_mapped_channel) shopifyql_mapped_channel, UPPER(ShopifyQL.shopifyql_mapped_source) shopifyql_mapped_source, UPPER(ShopifyQL.FIRSTVISIT_UTM_SOURCE) Shopifyql_FIRSTVISIT_UTM_SOURCE, UPPER(ShopifyQL.FirstVisit_UTM_Campaign) Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, upper(ShopifyQL.LastVisit_UTM_Campaign) Shopifyql_LAST_VISIT_UTM_CAMPAIGN, UPPER(ShopifyQL.LAST_MOMENT_UTM_SOURCE) Shopifyql_LAST_MOMENT_UTM_SOURCE, UPPER(ShopifyQL.LastVisit_NON_UTM_Source) Shopifyql_LAST_VISIT_NON_UTM_SOURCE, UPPER(ShopifyQL.LAST_MOMENT_UTM_MEDIUM) Shopifyql_LAST_MOMENT_UTM_MEDIUM, UPPER(ShopifyQL.FIRSTVISIT_UTM_MEDIUM) Shopifyql_FIRSTVISIT_UTM_MEDIUM, div0(ShopifyQL.MOMENTS_COUNT, count(1) over (partition by AO.name)) MOMENTS_COUNT, div0(ShopifyQL.DAYSTOCONVERT, count(1) over (partition by AO.name)) DAYSTOCONVERT, UPPER(GOKWIK.GOKWIK_UTM_SOURCE) GOKWIK_UTM_SOURCE, UPPER(GOKWIK.GOKWIK_UTM_MEDIUM) GOKWIK_UTM_MEDIUM, UPPER(GOKWIK.GOKWIK_UTM_CONTENT) GOKWIK_UTM_CONTENT, UPPER(GOKWIK.GOKWIK_MAPPED_CHANNEL) GOKWIK_MAPPED_CHANNEL, UPPER(GOKWIK.GOKWIK_MAPPED_SOURCE) GOKWIK_MAPPED_SOURCE, UPPER(Referrer_Name) Referrer_Name, UPPER(GOKWIK.GOKWIK_UTM_CAMPAIGN) GOKWIK_UTM_CAMPAIGN, UPPER( coalesce( affiliate.campaign_name, affiliate_campaign.campaign_name, GOKWIK_UTM_CAMPAIGN, LastVisit_UTM_Campaign ) ) FINAL_UTM_CAMPAIGN, Upper( coalesce( cao.source, GOKWIK_MAPPED_SOURCE, shopifyql_mapped_source, \'Direct\' ) ) FINAL_UTM_SOURCE, Upper( coalesce( GOKWIK_UTM_MEDIUM, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM ) ) FINAL_UTM_MEDIUM, coalesce(cao.channel, Upper( case when upper(coalesce( GOKWIK_MAPPED_CHANNEL, shopifyql_mapped_channel)) = \'DIRECT\' then coalesce(affiliate.channel, trackier.channel, \'Direct\') else coalesce( GOKWIK_MAPPED_CHANNEL, shopifyql_mapped_channel, affiliate.channel, trackier.channel, \'Direct\' ) end )) FINAL_UTM_CHANNEL, upper( coalesce(affiliate.affiliate, trackier.affiliate) ) final_affiliate, upper(trackier.affiliate) trackier_affiliate,case when upper( coalesce( affiliate.affiliate, trackier.affiliate, FINAL_UTM_SOURCE ) ) in ( \'GOOGLEPAY\', \'PHONEPE\', \'JIO\', \'ZOMATO\', \'PAYTM\', \'MAGICPIC\', \'TOGETHR\' ) then upper( coalesce( affiliate.channel, trackier.affiliate, FINAL_UTM_SOURCE ) ) else null end as affiliate_finance, trackier_payout, combined_timestamp trackier_date from ( select *, \'Shopify_justherbs\' AS Shop_Name from datalake_db.justherbs.trn_Shopify_jh_ORDERS ) AO left join ( select * from prd_db.justherbs.DWH_SHOPIFY_JH_UTM_PARAMETERS qualify row_number() over (partition by name order by 1) = 1 ) ShopifyQL on AO.name = ShopifyQL.name left join prd_db.justherbs.dwh_GOKWIK_SOURCE GOKWIK on AO.ID = GOKWIK.ID left join ( select txn_id, cast( case when replace(replace(payout, \',\', \'\'), \'-\', 0) = \'\' then 0 else replace(replace(payout, \',\', \'\'), \'-\', 0) end as float ) trackier_payout, publisher_name as affiliate, try_TO_TIMESTAMP( created_Date || \' \' || created_time, \'DD-MM-YYYY HH24:MI:SS\' ) AS combined_timestamp, \'Affiliates (CPS)\' channel from datalake_db.justherbs.trn_s3_trackier_data qualify row_number() over (partition by txn_id order by combined_timestamp) = 1 ) trackier on ao.name = trackier.txn_id left join ( select coupon, channel, \"Affiliate Name\" affiliate, \"Campaign Name\" campaign_name from datalake_db.justherbs.mst_affiliate_coupon_code where type = \'Coupon Prefix\' ) affiliate on lower(AO.discount_codes) like \'%\' || lower(affiliate.coupon) || \'%\' left join ( select coupon, channel, \"Campaign Name\" campaign_name from datalake_db.justherbs.mst_affiliate_coupon_code where type = \'utm_campaign\' ) affiliate_campaign on UPPER(coalesce(GOKWIK_UTM_CAMPAIGN, LastVisit_UTM_Campaign)) = upper(affiliate_campaign.coupon) left join datalake_db.justherbs.gsheet_custom_app_orders cao on AO.app_id = cao.app_id qualify row_number() over (partition by ao.name order by len(affiliate.coupon) desc) = 1; ALTER TABLE prd_db.justherbs.dwh_Shopify_All_orders RENAME COLUMN _AIRBYTE_trn_Shopify_jh_ORDERS_HASHID to _AIRBYTE_ORDERS_HASHID; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_products AS select *, \'Shopify_justherbs\' AS Shop_Name from datalake_db.justherbs.trn_Shopify_jh_PRODUCTS; ALTER TABLE prd_db.justherbs.dwh_Shopify_All_products RENAME COLUMN _AIRBYTE_trn_Shopify_jh_PRODUCTS_HASHID to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_products_variants AS select *, \'Shopify_justherbs\' AS Shop_Name from datalake_db.justherbs.trn_Shopify_jh_PRODUCTS_VARIANTS; ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_ALL_PRODUCTS_VARIANTS RENAME COLUMN _AIRBYTE_trn_Shopify_jh_PRODUCTS_HASHID to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_customers_addresses AS select *, \'Shopify_justherbs\' AS Shop_Name from datalake_db.justherbs.trn_Shopify_jh_CUSTOMERS_ADDRESSES; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_orders_items_discount AS SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, SUM(B.VALUE:amount::FLOAT) AS DISCOUNT FROM prd_db.justherbs.dwh_Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS) A, LATERAL FLATTEN (INPUT => A.VALUE:discount_allocations) B GROUP BY order_id, LINE_ITEM_ID; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_orders_items_tax AS SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, SUM(B.VALUE:price::FLOAT) AS TAX, SUM(B.VALUE:rate::FLOAT) AS Tax_Rate FROM prd_db.justherbs.DWH_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => LINE_ITEMS) A, LATERAL FLATTEN (INPUT => A.VALUE:tax_lines) B GROUP BY order_id, LINE_ITEM_ID; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_Refunds AS WITH base_refunds AS ( SELECT refunds.value AS refund_val, refunds.value:order_id::STRING AS order_id, try_to_timestamp(replace(refunds.value:\"created_at\", \'\"\', \'\')) AS refund_date FROM prd_db.justherbs.dwh_Shopify_All_orders, LATERAL FLATTEN(input => refunds) refunds ), refund_line_items AS ( SELECT order_id, line_items.value:line_item_id::STRING AS LINE_ITEM_ID, refund_date, SUM(IFNULL(line_items.value:quantity::INT, 0)) AS refund_quantity, SUM(IFNULL(line_items.value:subtotal::FLOAT, 0)) AS refund_subtotal FROM base_refunds, LATERAL FLATTEN(input => refund_val:refund_line_items) line_items GROUP BY order_id, LINE_ITEM_ID, refund_date ), order_adjustments AS ( SELECT order_id, refund_date AS adjustment_date, SUM(IFNULL(order_adj.value:amount::FLOAT, 0)) AS adjustment FROM base_refunds, LATERAL FLATTEN(input => refund_val:order_adjustments) order_adj GROUP BY order_id, refund_date ), adj_refund AS ( SELECT DISTINCT coalesce(rl.order_id, oa.order_id) AS order_id, rl.line_item_id, coalesce(oa.adjustment_date, rl.refund_date) AS date FROM refund_line_items rl FULL OUTER JOIN order_adjustments oa ON rl.order_id = oa.order_id ), refund_summary AS ( SELECT ar.order_id, ar.line_item_id, ar.date, IFNULL(rl.refund_quantity, 0) AS refund_quantity, IFNULL(rl.refund_subtotal, 0) AS refund_subtotal, IFNULL(div0(oa.adjustment, count(1) over (partition by ar.order_id, ar.date)), 0) AS Adjustment_amount, IFNULL(rl.refund_subtotal, 0) - IFNULL(div0(oa.adjustment, count(1) over (partition by ar.order_id, ar.date)), 0) AS Total_Refund FROM adj_refund ar LEFT JOIN refund_line_items rl ON ar.order_id = rl.order_id AND ar.date = rl.refund_date AND ar.line_item_id = rl.line_item_id LEFT JOIN order_adjustments oa ON ar.order_id = oa.order_id AND ar.date = oa.adjustment_date ) SELECT order_id, line_item_id, date AS refund_Date, SUM(refund_quantity) AS Quantity, SUM(Total_Refund) AS Amount, SUM(Adjustment_amount) AS Adjustment_Amount, SUM(refund_subtotal) AS Refund_Before_Adjustment, ARRAY_AGG( Object_construct( \'Refund_Date\', date, \'Refund_Quantity\', IFNULL(to_varchar(CAST(refund_quantity AS DECIMAL(38, 2))), \'0\'), \'Adjustment_Amount\', IFNULL(to_varchar(CAST(Adjustment_amount AS DECIMAL(38, 2))), \'0\'), \'Refund_Amount\', IFNULL(to_varchar(CAST(Total_Refund AS DECIMAL(38, 2))), \'0\') ) ) AS Refund_Details FROM refund_summary GROUP BY order_id, line_item_id, date; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_orders_fulfillment AS SELECT A.value:order_id AS order_id, B.value:id AS Line_Item_ID, replace(A.VALUE:tracking_number, \'\"\', \'\') AS AWB, Upper(replace(A.VALUE:tracking_company, \'\"\', \'\')) AS Courier, Upper(replace(A.VALUE:shipment_status, \'\"\', \'\')) AS Shipping_status, replace(A.VALUE:updated_at, \'\"\', \'\') AS shipping_status_update_date, replace(A.VALUE:tracking_url, \'\"\', \'\') AS tracking_url, replace(A.VALUE:created_at, \'\"\', \'\') AS Shipping_created_at FROM prd_db.justherbs.DWH_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => fulfillments) A, LATERAL FLATTEN (INPUT => A.value:line_items) B; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_discount_codes AS SELECT id, replace(A.value:code, \'\"\', \'\') AS code FROM prd_db.justherbs.DWH_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => discount_codes) A qualify row_number() over (partition by id order by code) = 1; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_Shopify_All_orders_items AS WITH CTE AS ( SELECT SHOP_NAME, ID::VARCHAR(16777216) AS ORDER_ID, NAME AS ORDER_NAME, CUSTOMER, replace(customer:default_address:name, \'\"\', \'\') NAME, coalesce(phone, replace(customer:default_address:phone, \'\"\', \'\')) phone, coalesce(email, replace(customer:email, \'\"\', \'\')) email, replace(shipping_address:zip, \'\"\', \'\') pincode, tags, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, A.VALUE:product_id::STRING AS PRODUCT_ID, A.VALUE:title::STRING AS PRODUCT_NAME, CURRENCY, CASE WHEN cancelled_at IS NOT NULL THEN \'CANCELLED\' ELSE \'Shopify_Processed\' END AS order_status, CREATED_AT::DATETIME AS order_timestamp, A.VALUE:price::FLOAT offer_price, A.VALUE:price::FLOAT * A.VALUE:quantity::FLOAT AS LINE_ITEM_SALES, ( TOTAL_SHIPPING_PRICE_SET:presentment_money:amount::FLOAT / COUNT(ORDER_ID) OVER(PARTITION BY ORDER_ID) ) AS SHIPPING_PRICE, A.value:price/(1 + A.value:tax_lines:rate), A.VALUE:quantity::FLOAT as QUANTITY, \'Shopify\' AS Source, MOMENTS_COUNT, DAYSTOCONVERT, SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, SHOPIFYQL_MAPPED_CHANNEL, SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, Shopifyql_LAST_VISIT_NON_UTM_SOURCE, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, FINAL_UTM_CHANNEL, FINAL_UTM_SOURCE, FINAL_UTM_CAMPAIGN, FINAL_UTM_MEDIUM, Referrer_Name, NULL as product_sub_category, payment_gateway_names, discount_codes, final_affiliate, trackier_affiliate, affiliate_finance, trackier_payout, trackier_date FROM prd_db.justherbs.DWH_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => LINE_ITEMS) A ) SELECT CTE.*, DC.code AS discount_code, IFNULL(T.TAX_RATE, 0) AS TAX_RATE, IFNULL(D.DISCOUNT, 0) AS DISCOUNT, CTE.LINE_ITEM_SALES AS GROSS_SALES_AFTER_TAX, CTE.LINE_ITEM_SALES / (1 + IFNULL(T.TAX_RATE, 0)) AS GROSS_SALES_BEFORE_TAX, IFNULL(D.DISCOUNT, 0) / (1 + IFNULL(T.TAX_RATE, 0)) AS DISCOUNT_BEFORE_TAX, CTE.LINE_ITEM_SALES / (1 + IFNULL(T.TAX_RATE, 0)) - IFNULL(D.DISCOUNT, 0) / (1 + IFNULL(T.TAX_RATE, 0)) AS NET_SALES_BEFORE_TAX, CASE WHEN IFNULL(T.TAX, 0) = 0 THEN CTE.LINE_ITEM_SALES * tax_rate ELSE IFNULL(T.TAX, 0) END AS TAX, CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT, 0) + CTE.SHIPPING_PRICE - IFNULL( div0(RE.AMOUNT, count(1) over (partition by CTE.order_id)), 0 ) AS TOTAL_SALES, CASE WHEN R.amount IS NOT NULL THEN 1 ELSE 0 END AS IS_REFUND, R.REFUND_DETAILS, R.QUANTITY AS Refund_Quantity, R.AMOUNT AS Refund_Value, div0(RE.AMOUNT, count(1) over (partition by CTE.order_id)) AS refund_amount_without_lineitem, F.AWB AS AWB, F.SHIPPING_STATUS AS Shopify_Shipping_Status, F.SHIPPING_STATUS_UPDATE_DATE AS Shopify_Shipping_Updated_Date, F.COURIER AS SHOPIFY_COURIER FROM CTE LEFT JOIN prd_db.justherbs.DWH_SHOPIFY_ALL_ORDERS_ITEMS_TAX T ON CTE.ORDER_ID = T.ORDER_ID AND CTE.LINE_ITEM_ID = T.LINE_ITEM_ID LEFT JOIN prd_db.justherbs.dwh_Shopify_All_orders_items_discount D ON CTE.ORDER_ID = D.ORDER_ID AND CTE.LINE_ITEM_ID = D.LINE_ITEM_ID LEFT JOIN prd_db.justherbs.DWH_SHOPIFY_ALL_REFUNDS R ON CTE.ORDER_ID = R.ORDER_ID AND CTE.LINE_ITEM_ID = R.LINE_ITEM_ID LEFT JOIN prd_db.justherbs.DWH_SHOPIFY_ALL_REFUNDS RE ON CTE.ORDER_ID = RE.ORDER_ID AND RE.line_item_id IS NULL LEFT JOIN prd_db.justherbs.DWH_SHOPIFY_ALL_ORDERS_FULFILLMENT F ON CTE.ORDER_ID = F.ORDER_ID AND CTE.LINE_ITEM_ID = F.LINE_ITEM_ID LEFT JOIN prd_db.justherbs.dwh_Shopify_All_discount_codes DC ON CTE.order_id = DC.id; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS_INTERMEDIATE AS SELECT O.SHOP_NAME, O.ORDER_ID, O.ORDER_NAME, O.CUSTOMER:id::int AS customer_id, O.Name, O.EMAIL, o.pincode, O.PHONE, O.Tags, O.LINE_ITEM_ID, O.SKU, O.PRODUCT_ID, O.CURRENCY, O.IS_REFUND, COALESCE(NULLIF(upper(CD.city), \'\'), \'NA\') AS city, COALESCE(NULLIF(upper(CD.province), \'\'), \'NA\') AS state, COALESCE(NULLIF(P.title, \'\'), \'NA\') AS product_name, COALESCE(NULLIF(P.product_type, \'\'), \'NA\') AS category, P.price_range_v2:max_variant_price:amount::float AS mrp, o.quantity * P.price_range_v2:max_variant_price:amount::float AS mrp_sales, O.order_status, O.order_timestamp, offer_price, O.LINE_ITEM_SALES, O.SHIPPING_PRICE, O.QUANTITY, O.TAX, O.TAX_RATE, O.DISCOUNT, O.DISCOUNT_BEFORE_TAX, O.GROSS_SALES_AFTER_TAX, O.GROSS_SALES_BEFORE_TAX, O.NET_SALES_BEFORE_TAX, O.TOTAL_SALES, O.Source, O.MOMENTS_COUNT, O.DAYSTOCONVERT, O.SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, O.SHOPIFYQL_MAPPED_CHANNEL, O.SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, O.Shopifyql_LAST_VISIT_NON_UTM_SOURCE, O.Shopifyql_FIRSTVISIT_UTM_MEDIUM, O.Shopifyql_LAST_MOMENT_UTM_MEDIUM, O.FINAL_UTM_CHANNEL, O.FINAL_UTM_CAMPAIGN, O.FINAL_UTM_SOURCE, o.FINAL_UTM_MEDIUM, O.Referrer_Name, o.final_affiliate, o.trackier_affiliate, o.affiliate_finance, O.AWB, O.SHOPIFY_SHIPPING_STATUS, O.SHOPIFY_SHIPPING_UPDATED_DATE, O.SHOPIFY_COURIER, O.Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, O.Shopifyql_LAST_VISIT_UTM_CAMPAIGN, o.product_sub_category sub_Category, o.discount_code, payment_gateway_names, o.REFUND_DETAILS, o.Refund_Quantity, o.Refund_Value, trackier_payout, trackier_date FROM prd_db.justherbs.DWH_SHOPIFY_ALL_ORDERS_ITEMS O LEFT JOIN prd_db.justherbs.dwh_Shopify_All_products P ON O.PRODUCT_ID = P.id LEFT JOIN ( SELECT customer_id, city, province FROM prd_db.justherbs.dwh_Shopify_All_customers_addresses qualify row_number() OVER (partition BY customer_id ORDER BY id DESC) = 1 ) CD ON O.CUSTOMER:id::int = CD.customer_id; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS_TEMP_Category AS SELECT fi.*, fi.SKU AS SKU_CODE, Upper(coalesce(p.name, fi.product_name)) AS PRODUCT_NAME_Final, coalesce(upper(pc.category), Upper(p.CATEGORY), upper(fi.category)) AS Product_Category, coalesce(upper(pc.subcategory), Upper(p.sub_category), upper(fi.Sub_Category)) AS Product_Sub_Category, p.BRAND FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS_INTERMEDIATE fi LEFT JOIN ( SELECT SKU AS skucode, UPPER(product_name) AS name, upper(category_name) AS CATEGORY, null AS sub_category, upper(brand) AS Brand FROM datalake_db.justherbs.mst_easyecom_jh_product_master qualify row_number() over (partition by SKU order by 1) = 1 ) p ON fi.sku = p.skucode LEFT JOIN ( SELECT sku, category, subcategory FROM datalake_db.justherbs.mst_googlesheet_product_category qualify row_number() over (partition by sku order by 1) = 1 ) pc ON lower(fi.sku) = lower(pc.sku); CREATE OR REPLACE TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS_INTERMEDIATE AS SELECT * FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS_TEMP_Category; create or replace table prd_db.justherbs.dwh_Shopify_Final_customerID as with clean_contacts as ( SELECT DISTINCT right(regexp_replace(replace(phone, \' \', \'\'), \'[^a-zA-Z0-9]+\'), 10) AS contact_num, email FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS_INTERMEDIATE ), new_phone_numbers as ( SELECT contact_num, 19700000000 + row_number() over (order by contact_num asc) AS maple_monk_id FROM (SELECT DISTINCT contact_num FROM clean_contacts) ), int as ( SELECT c.contact_num, c.email, coalesce( p.maple_monk_id, 19800000000 + row_number() over (partition by p.maple_monk_id is NULL order by c.email asc) ) AS maple_monk_id FROM clean_contacts c LEFT JOIN new_phone_numbers p ON c.contact_num = p.contact_num ) SELECT contact_num, email, maple_monk_id FROM int WHERE coalesce(contact_num, email) IS NOT NULL; create or replace table prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS as select coalesce(c.maple_monk_id, d.maple_monk_id) as Shopify_customer_id_final, min(ORDER_TIMESTAMP::date) over(partition by Shopify_customer_id_final) as shopify_acquisition_date, min( case when lower(order_status) not in (\'cancelled\') then ORDER_TIMESTAMP::date end ) over(partition by Shopify_customer_id_final) as shopify_first_complete_order_date, c.maple_monk_id as maple_monk_id_phone, o.* from prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS_INTERMEDIATE o left join ( select contact_num as phone, maple_monk_id from prd_db.justherbs.dwh_Shopify_Final_customerID qualify row_number() over (partition by contact_num order by maple_monk_id asc) = 1 ) c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'), 10) left join ( select distinct maple_monk_id, email from prd_db.justherbs.dwh_Shopify_Final_customerID where contact_num is null ) d on d.email = o.email; ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_new_customer_flag varchar(50); ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_new_customer_flag_month varchar(50); ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_customer_segment varchar(50); ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_acquisition_product varchar(16777216); ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_acquisition_channel varchar(16777216); ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_acquisition_source varchar(16777216); ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_acquisition_coupon varchar(16777216); ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_acquisition_category varchar(16777216); UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS AS A SET A.shopify_new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, Shopify_customer_id_final, ORDER_TIMESTAMP, CASE WHEN order_timestamp::date <> shopify_acquisition_date THEN \'Repeat\' ELSE \'New\' END AS Flag FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ) AS B WHERE A.order_id = B.order_id AND A.Shopify_customer_id_final = B.Shopify_customer_id_final AND A.ORDER_TIMESTAMP::date = B.ORDER_TIMESTAMP::Date; UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS SET shopify_new_customer_flag = \'New\' WHERE shopify_new_customer_flag IS NULL; UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS AS A SET A.shopify_new_customer_flag_month = B.flag FROM ( SELECT order_id, shopify_customer_id_final, CASE WHEN Last_day(ORDER_TIMESTAMP, \'month\') = Last_day(shopify_first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(ORDER_TIMESTAMP, \'month\') < Last_day(shopify_first_complete_order_date, \'month\') OR shopify_acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN Last_day(ORDER_TIMESTAMP, \'month\') > Last_day(shopify_first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ) AS B WHERE A.order_id = B.order_id AND A.shopify_customer_id_final = B.shopify_customer_id_final; UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS SET shopify_new_customer_flag_month = \'New\' WHERE shopify_new_customer_flag_month IS NULL AND (lower(order_status) IS NULL OR lower(order_status) NOT IN (\'cancelled\')); UPDATE prd_db.justherbs.dwh_shopify_fact_items A SET shopify_customer_segment = B.segment FROM ( SELECT shopify_customer_id_final, order_date, CASE WHEN prev_unique_order_date IS NULL THEN \'Lifetime New\' WHEN DATEDIFF(day, prev_unique_order_date, order_date) <= 90 THEN \'Super Active\' WHEN DATEDIFF(day, prev_unique_order_date, order_date) <= 180 THEN \'Active\' WHEN DATEDIFF(day, prev_unique_order_date, order_date) <= 365 THEN \'Dormant\' ELSE \'Inactive\' END AS segment FROM ( SELECT shopify_customer_id_final, order_date, LAG(order_date) OVER (PARTITION BY shopify_customer_id_final ORDER BY order_date) AS prev_unique_order_date FROM ( SELECT DISTINCT shopify_customer_id_final, order_timestamp::DATE AS order_date FROM prd_db.justherbs.dwh_shopify_fact_items ) ) ) B WHERE A.shopify_customer_id_final = B.shopify_customer_id_final AND A.order_timestamp::DATE = B.order_date; CREATE OR replace temporary TABLE prd_db.justherbs.dwh_temp_source_1 AS SELECT DISTINCT shopify_customer_id_final, channel, source FROM ( SELECT DISTINCT shopify_customer_id_final, order_timestamp::date order_Date, FINAL_UTM_SOURCE as SOURCE, FINAL_UTM_CHANNEL as CHANNEL, Min( case when lower(order_status) not in (\'cancelled\') then order_timestamp::date end ) OVER (partition BY shopify_customer_id_final) firstOrderdate FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ) res WHERE order_date = firstorderdate; UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS AS a SET a.shopify_acquisition_channel = b.channel FROM prd_db.justherbs.dwh_temp_source_1 b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS AS a SET a.shopify_acquisition_source = b.SOURCE FROM prd_db.justherbs.dwh_temp_source_1 b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; CREATE OR replace temporary TABLE prd_db.justherbs.dwh_temp_product_1 AS SELECT DISTINCT shopify_customer_id_final, product_name_final, product_category, Row_number() OVER ( partition BY shopify_customer_id_final ORDER BY total_sales DESC ) rowid FROM ( SELECT DISTINCT shopify_customer_id_final, order_timestamp::date order_date, product_name_final, product_category, TOTAL_SALES, Min( case when lower(order_status) not in (\'cancelled\') then order_timestamp::date end ) OVER (partition BY shopify_customer_id_final) firstOrderdate FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ) res WHERE order_date = firstorderdate; select * from prd_db.justherbs.dwh_temp_product_1; UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS AS A SET A.shopify_acquisition_product = B.product_name_final, A.shopify_acquisition_category = B.product_category FROM ( SELECT * FROM prd_db.justherbs.dwh_temp_product_1 WHERE rowid = 1 ) B WHERE A.shopify_customer_id_final = B.shopify_customer_id_final; CREATE OR replace temporary TABLE prd_db.justherbs.dwh_temp_coupon_1 AS SELECT DISTINCT shopify_customer_id_final, discount_code, Row_number() OVER ( partition BY shopify_customer_id_final ORDER BY total_sales DESC ) rowid FROM ( SELECT DISTINCT shopify_customer_id_final, order_timestamp::date order_date, discount_code, TOTAL_SALES, Min( case when lower(order_status) not in (\'cancelled\') then order_timestamp::date end ) OVER (partition BY shopify_customer_id_final) firstOrderdate FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ) res WHERE order_date = firstorderdate; UPDATE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS AS A SET A.shopify_acquisition_coupon = B.discount_code FROM ( SELECT * FROM prd_db.justherbs.dwh_temp_coupon_1 WHERE rowid = 1 ) B WHERE A.shopify_customer_id_final = B.shopify_customer_id_final; ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN SHIPPING_TAX FLOAT; ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN SHIP_PROMOTION_DISCOUNT FLOAT; ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN GIFT_WRAP_PRICE FLOAT; ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ADD COLUMN GIFT_WRAP_TAX FLOAT; ALTER TABLE prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS MODIFY COLUMN ORDER_STATUS VARCHAR(100);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PRD_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
